#include <DungeonEntrySql.hpp>
#include <item/DungeonEntry.hpp>
#include <item/DungeonEntryBindings.hpp>
#include <item/DungeonItems.hpp>
void DungeonEntryCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==10,"all10 original dungeon entry definitions loaded");const auto found=std::ranges::find_if(catalog->Entries(),[](const auto& p){return p.second.base.contentCode=="catalog.10.ticket_of_the_runes_8546eaf0058e";});Check(found!=catalog->Entries().end(),"original Rune entry ticket resolved by authored native content code");const auto ticket=found->first;
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned dungeon SQL connects");
 auto query=[&](const std::string& text){std::unique_ptr<SQLMsg> r(sql.DirectQuery(text.c_str()));Check(r && !r->uiSQLErrno && r->Get(),"owned dungeon fixture query succeeds");return r;};
 auto scalar=[&](const std::string& text){auto r=query(text);const auto row=r->Get()->FetchRow();Check(row && row[0],"dungeon scalar exists");return std::string(row[0]);};
 auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-dungeon-entry-worker").has_value(),"actual dungeon entry item worker starts");
 std::vector<persistence::LoadedItemOwner> states;for(unsigned n=0;n<8;++n){ItemOwner owner{ItemOwnerKind::Character,25001+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,3}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"native party participant provisioned");states.push_back(persistence::LoadCurrentItemOwner(sql,*catalog,owner).value());}
 for(const auto& b:DungeonEntryBindings){const auto key=DungeonItemKey(*catalog,b.ticketCode);Check(key && std::ranges::any_of(sources,[&](const auto& source){return source.grant.key==*key;}),"every authored dungeon map resolves one of the ten actual native entry sources");}
 unsigned serial=0,packets=0;bool replay=false;const auto now=[](){return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());};const auto op=[&](){++serial;return std::array<std::uint8_t,16>{0x58,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
 const auto wait=[&](const auto& done){for(unsigned n=0;!done() && n<2000;++n){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(5));}Check(done(),"actual dungeon entry completion returned");};
 const auto apply=[&](const ItemCommit& commit,bool expected=true){std::vector<runtime::OwnerRead> reads;for(const auto& f:commit.owners)reads.push_back({f.owner,f.sessionGeneration});std::optional<runtime::MultiCommitOutcome> out;Check(runtime::RequestCommitMany(reads,commit,[&](auto result){out=std::move(result);}),"dungeon item transaction queued");wait([&](){return out.has_value();});if(out->write.has_value()!=expected)std::cerr<<"DUNGEON_SQL_ERROR="<<(out->write?-1:static_cast<int>(out->write.error()))<<" serial="<<serial<<'\n';Check(out->write.has_value()==expected,"dungeon SQL write matches expected outcome");replay=out->write && out->write->replay;for(auto& row:out->states)if(row)for(auto& state:states)if(state.fence.owner==row->fence.owner){state=std::move(*row);break;}};
 std::uint64_t nextId=90000000;
 for(auto& state:states){const std::array ids{ItemInstanceId::Create(++nextId).value()};const auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,{ticket,0,3},ids);Check(grant.has_value(),"real source ticket grant planned");apply(*grant);}
 // Existing Rune leftovers must be removed in the same debit, before warp.
 for(const auto code:{std::string_view("dungeon.rune.fragment"),std::string_view("dungeon.rune.floor_key"),std::string_view("catalog.10.ticket_of_the_runes_78bafde9234a")}){const auto key=DungeonItemKey(*catalog,code);Check(key.has_value(),"real original Rune cleanup definition available");const std::array ids{ItemInstanceId::Create(++nextId).value(),ItemInstanceId::Create(++nextId).value(),ItemInstanceId::Create(++nextId).value()};auto& state=states.front();auto grant=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,{*key,0,3},ids);Check(grant.has_value(),"real original Rune leftovers granted");apply(*grant);}
 const auto file=[&](const std::string& phase,const char* kind,const auto& b){std::ofstream f(path+"."+phase+"."+kind+".hex");for(auto value:b){const auto v=static_cast<unsigned char>(value);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"actual dungeon frame exported");};
 const auto output=[&](const std::string& phase){const auto& state=states.front();file(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());std::ofstream facts(path+"."+phase+".json");facts<<"{\"owned\":"<<CountMissionItems(state.items,state.fence.owner,ticket,0)<<",\"party\":8,\"count_command\":\""<<DungeonEntryCountCommand(218,CountMissionItems(state.items,state.fence.owner,ticket,0))<<"\"}\n";++packets;};
 const auto allOwners=[&](){std::vector<ItemOwnerFence> all;for(const auto& s:states)all.push_back(s.fence);return all;};const auto allItems=[&](){std::vector<PersistentItem> all;for(const auto& s:states)all.insert(all.end(),s.items.begin(),s.items.end());return all;};const auto allLayouts=[&](){std::vector<ItemStorageLayout> all;for(const auto& s:states)all.insert(all.end(),s.storages.begin(),s.storages.end());return all;};
 output("before");const auto reserve=MakeDungeonEntryReservation(*catalog,op(),"dungeon.rune.entry",ticket,0,1,now(),allOwners(),allItems());Check(reserve && reserve->items.empty(),"all8 original entry tickets reserve without consuming");apply(*reserve);Check(scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="8","all8 SQL reservation locks active together");for(const auto& s:states)Check(s.items[0].count==3,"reservation never spends a ticket");output("reserved");apply(*reserve);Check(replay && scalar("SELECT COUNT(*) FROM player.item_dungeon_entry")=="8","reservation receipt replay creates no extra locks");
 auto& first=states.front();auto move=MakeMoveCommit(*catalog,op(),first.fence,first.storages,first.items,first.items[0].id,{ItemStorageKind::Inventory,1,20});Check(move.has_value(),"ordinary domain move has no access to SQL-only reservation overlay");apply(*move,false);Check(first.items[0].placement->anchor==0 && first.items[0].count==3,"central SQL guard prevents moving reserved instance without changing it");auto stolen=MakeConsumeCommit(*catalog,op(),first.fence,first.storages,first.items,first.items[0].id,1);Check(stolen.has_value(),"ordinary consume builds against visible native before-state");apply(*stolen,false);Check(first.items[0].count==3,"central SQL guard rejects ordinary consuming of reserved ticket");
 auto debit=MakeDungeonEntryResolution(*catalog,op(),*reserve->dungeonEntry,true,allOwners(),allLayouts(),allItems());Check(debit && debit->items.size()==13,"actual whole-party debit also removes all three original Rune leftover kinds atomically");auto stale=*debit;stale.operationId=op();--stale.owners.back().revision;apply(stale,false);Check(scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="8","one stale participant rolls back every owner and lock resolution");
 query("CREATE TRIGGER player.fail_entry_debit BEFORE UPDATE ON player.item_instance FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='entry debit failure'");apply(*debit,false);query("DROP TRIGGER player.fail_entry_debit");Check(scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="8","child write failure rolls back all lock resolutions as well as every item");
 apply(*debit);for(const auto& s:states)Check(s.items[0].count==2,"confirmed party debit spends exactly one source ticket per player");Check(scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="0","consumption releases all external locks atomically");Check(first.items.size()==1,"all old Rune fragment/key/cleanup ticket stacks removed before warp publication");output("consumed");apply(*debit);Check(replay && first.items[0].count==2,"debit receipt replay never spends a second ticket");output("replayed");
 const auto cancelled=MakeDungeonEntryReservation(*catalog,op(),"dungeon.rune.entry",ticket,0,1,now(),allOwners(),allItems()).value();apply(cancelled);const auto release=MakeDungeonEntryResolution(*catalog,op(),*cancelled.dungeonEntry,false,allOwners(),{},{});Check(release.has_value(),"failed dungeon creation plans release without a refund/grant");apply(*release);Check(scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="0" && first.items[0].count==2,"release preserves exact original instance and count");output("released");
 const std::array oneOwner{first.fence};const auto interrupted=MakeDungeonEntryReservation(*catalog,op(),"dungeon.rune.entry",ticket,0,1,now(),oneOwner,first.items).value();apply(interrupted);const auto oldSession=first.fence.sessionGeneration;std::optional<runtime::LoginLoad> login;Check(runtime::RequestLoginLoad(static_cast<unsigned>(first.fence.owner.id),[&](auto result){login=std::move(result);}),"actual native login recovery queued");wait([&](){return login.has_value();});Check(login->loaded.has_value(),"unspent reservation recovered before login inventory publication");first=std::move(*login->loaded);Check(first.fence.sessionGeneration>oldSession && first.items[0].count==2 && scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="0","relogin releases stale lock without losing or inventing ticket units");output("recovered");
 const std::array newOwner{first.fence};const auto newReservation=MakeDungeonEntryReservation(*catalog,op(),"dungeon.rune.entry",ticket,0,1,now(),newOwner,first.items).value();apply(newReservation);Check(!persistence::RecoverDungeonEntries(sql,*catalog,first.fence.owner,oldSession) && scalar("SELECT COUNT(*) FROM player.item_dungeon_entry WHERE active_instance IS NOT NULL")=="1","late old logout cannot release newer login's reservation");Check(persistence::RecoverDungeonEntries(sql,*catalog,first.fence.owner,first.fence.sessionGeneration).value()==1,"current authenticated session can release its own reservation");first=persistence::LoadCurrentItemOwner(sql,*catalog,first.fence.owner).value();
 for(const auto& source:sources)if(source.grant.key!=ticket){const std::array ids{ItemInstanceId::Create(++nextId).value()};auto grant=MakeGrantCommit(*catalog,op(),first.fence,first.storages,first.items,source.grant,ids);Check(grant.has_value(),"each other original entry prototype grants its real native state");apply(*grant);const std::array owner{first.fence};auto reservation=MakeDungeonEntryReservation(*catalog,op(),"dungeon.source.validation",source.grant.key,source.grant.refinementLevel,1,now(),owner,first.items);Check(reservation.has_value(),"each original material and quest ticket supports native reservation");apply(*reservation);const std::array current{first.fence};auto debit=MakeDungeonEntryResolution(*catalog,op(),*reservation->dungeonEntry,true,current,first.storages,first.items);Check(debit.has_value(),"each original ticket supports exact native entry debit");apply(*debit);Check(std::ranges::none_of(first.items,[&](const auto& i){return i.id==ids[0];}),"each concrete one-unit source ticket is removed after confirmed debit");}
 store.Stop();std::cout<<"SOURCE_DUNGEON_ENTRY_WORKER=SUCCESS sources=10 packets="<<packets<<" checks="<<checks<<std::endl;
}
